mkuse!{use rustc_data_structures :: graph ;}
mkuse!{use rustc_data_structures :: graph :: iterate :: DepthFirstSearch ;}
mkuse!{use rustc_data_structures :: graph :: reversed :: ReversedGraph ;}
mkuse!{use rustc_index :: Idx ;}
mkuse!{use rustc_index :: bit_set :: DenseBitSet ;}
mkitem!{mkstruct!{# [doc = " A view of an underlying graph that has been augmented to have “balanced\u{a0}flow”."] # [doc = " This means that the flow (execution count) of each node is equal to the"] # [doc = " sum of its in-edge flows, and also equal to the sum of its out-edge flows."] # [doc = ""] # [doc = " To achieve this, a synthetic \"sink\" node is non-destructively added to the"] # [doc = " graph, with synthetic in-edges from these nodes:"] # [doc = " - Any node that has no out-edges."] # [doc = " - Any node that explicitly requires a sink edge, as indicated by a"] # [doc = "   caller-supplied `force_sink_edge` function."] # [doc = " - Any node that would otherwise be unable to reach the sink, because it is"] # [doc = "   part of an inescapable loop."] # [doc = ""] # [doc = " To make the graph fully balanced, there is also a synthetic edge from the"] # [doc = " sink node back to the start node."] # [doc = ""] # [doc = " ---"] # [doc = " The benefit of having a balanced-flow graph is that it can be subsequently"] # [doc = " transformed in ways that are guaranteed to preserve balanced flow"] # [doc = " (e.g. merging nodes together), which is useful for discovering relationships"] # [doc = " between the node flows of different nodes in the graph."] pub (crate) struct BalancedFlowGraph < G : graph :: DirectedGraph > { graph : G , sink_edge_nodes : DenseBitSet < G :: Node > , pub (crate) sink : G :: Node , }}}
mkitem!{mkimpl!{impl < G : graph :: DirectedGraph > BalancedFlowGraph < G > { # [doc = " Creates a balanced view of an underlying graph, by adding a synthetic"] # [doc = " sink node that has in-edges from nodes that need or request such an edge,"] # [doc = " and a single out-edge to the start node."] # [doc = ""] # [doc = " Assumes that all nodes in the underlying graph are reachable from the"] # [doc = " start node."] pub (crate) fn for_graph (graph : G , force_sink_edge : impl Fn (G :: Node) -> bool) -> Self where G : graph :: ControlFlowGraph , { let mut sink_edge_nodes = DenseBitSet :: new_empty (graph . num_nodes ()) ; let mut dfs = DepthFirstSearch :: new (ReversedGraph :: new (& graph)) ; for node in graph . iter_nodes () { if force_sink_edge (node) || graph . successors (node) . next () . is_none () { sink_edge_nodes . insert (node) ; dfs . push_start_node (node) ; } } dfs . complete_search () ; sink_edge_nodes . union_not (dfs . visited_set ()) ; let sink = G :: Node :: new (graph . num_nodes ()) ; BalancedFlowGraph { graph , sink_edge_nodes , sink } } }}}
mkitem!{mkimpl!{impl < G > graph :: DirectedGraph for BalancedFlowGraph < G > where G : graph :: DirectedGraph , { type Node = G :: Node ; # [doc = " Returns the number of nodes in this balanced-flow graph, which is 1"] # [doc = " more than the number of nodes in the underlying graph, to account for"] # [doc = " the synthetic sink node."] fn num_nodes (& self) -> usize { self . sink . index () + 1 } }}}
mkitem!{mkimpl!{impl < G > graph :: StartNode for BalancedFlowGraph < G > where G : graph :: StartNode , { fn start_node (& self) -> Self :: Node { self . graph . start_node () } }}}
mkitem!{mkimpl!{impl < G > graph :: Successors for BalancedFlowGraph < G > where G : graph :: StartNode + graph :: Successors , { fn successors (& self , node : Self :: Node) -> impl Iterator < Item = Self :: Node > { let real_edges ; let sink_edge ; if node == self . sink { real_edges = None ; sink_edge = Some (self . graph . start_node ()) ; } else { real_edges = Some (self . graph . successors (node)) ; sink_edge = self . sink_edge_nodes . contains (node) . then_some (self . sink) ; } real_edges . into_iter () . flatten () . chain (sink_edge) } }}}